def unique_jobs(rows):
    seen = {}
    result = []

    for r in rows:
        source = r.get('source')
        source_id = r.get('source_id')

        # Build key: (source, source_id) where None/empty string are preserved as-is
        key = (source, source_id)

        if key not in seen:
            seen[key] = True
            result.append(r)

    return result
